71: export function deriveStats(unit) {
72:   const job = jobOf(unit);
73:   const s = {
74:     maxHp: unit.base.hp + job.bonus.hp,
75:     maxMp: unit.base.mp + job.bonus.mp,
76:     pa: unit.base.pa + job.bonus.pa,
77:     ma: unit.base.ma + job.bonus.ma,
78:     def: unit.base.def + job.bonus.def,
79:     res: unit.base.res + job.bonus.res,
80:     spd: unit.base.spd + job.bonus.spd,
81:     luck: unit.base.luck + (job.bonus.luck || 0),
82:     move: job.move,
83:     jump: job.jump,
84:   };
85:   for (const slot of ['weapon', 'armor', 'accessory']) {
86:     const id = unit.equipment?.[slot];
87:     if (!id) continue;
88:     const it = ITEM_MAP[id];
89:     if (!it) continue;
90:     for (const k of ['hp', 'mp', 'pa', 'ma', 'def', 'res', 'spd', 'move', 'luck']) {
91:       if (!it[k]) continue;
92:       if (k === 'hp') s.maxHp += it.hp;
93:       else if (k === 'mp') s.maxMp += it.mp;
94:       else s[k] += it[k];
95:     }
96:   }
97:   const w = weaponOf(unit);
98:   s.weapon = w;
99:   s.maxHp = Math.max(1, Math.round(s.maxHp));
100:   s.maxMp = Math.max(0, Math.round(s.maxMp));
101:   s.pa = Math.max(1, Math.round(s.pa));
102:   s.ma = Math.max(0, Math.round(s.ma));
103:   s.def = Math.max(0, Math.round(s.def));
104:   s.res = Math.max(0, Math.round(s.res));
105:   s.spd = Math.max(1, Math.round(s.spd));
106:   s.move = Math.max(1, Math.round(s.move));
107:   s.jump = Math.max(1, Math.round(s.jump));
108:   return s;
109: }
