125:   if ((unit.arts?.[art.job] || []).includes(art.id)) return { ok: false, reason: 'Known' };
126:   if (jobRank(unit, art.job) < (art.req || 0)) return { ok: false, reason: `Requires rank ${(art.req || 0) + 1}` };
127:   if (unit.jp < art.jp) return { ok: false, reason: 'Not enough JP' };
