142: export function changeJob(unit, jobId, force = false) {
143:   const job = JOBS[jobId];
144:   if (!job) return { ok: false, reason: 'No such job' };
145:   if (job.tier && !force && !(unit.unlockedJobs || []).includes(jobId)) {
146:     return { ok: false, reason: 'Promotion required' };
147:   }
148:   unit.job = jobId;
149:   unit.arts[jobId] = unit.arts[jobId] || [];
150:   const free = job.arts.filter(a => (a.req || 0) === 0);
151:   for (const a of free) if (!unit.arts[jobId].includes(a.id)) unit.arts[jobId].push(a.id);
152:   return { ok: true, job };
153: }
