175: export function promoteUnit(state, unit) {
176:   const check = canPromote(state, unit);
177:   if (!check.ok) return check;
178:   const target = check.target;
179:   const baseJobId = unit.job;
180:   state.inventory.crownSeal = Math.max(0, (state.inventory.crownSeal || 0) - 1);
181:   unit.promoted = true;
182:   unit.advancedJob = target.id;
183:   unit.unlockedJobs = Array.from(new Set([...(unit.unlockedJobs || []), target.id]));
184:   // Carry every learned Art from the base class into the advanced class.
185:   const carried = unit.arts[baseJobId] || [];
186:   unit.arts[target.id] = Array.from(new Set([...carried, ...target.arts.filter(a => (a.req || 0) === 0).map(a => a.id)]));
187:   changeJob(unit, target.id, true);
188:   return { ok: true, job: target };
189: }
