211: export function canEquipItem(state, unit, slot, itemId) {
212:   const item = ITEM_MAP[itemId];
213:   if (!item) return { ok: false, reason: 'Unknown item' };
214:   if (item.slot !== slot) return { ok: false, reason: 'Wrong slot' };
215:   if (slot === 'weapon' && !jobAllowedWeapon(unit, item)) return { ok: false, reason: `${jobOf(unit).name}s cannot wield ${item.type}s` };
216:   const already = unit.equipment?.[slot] === itemId ? 1 : 0;
217:   if (owned(state, itemId) < equippedElsewhere(state, unit.id, slot, itemId) + 1 - already) {
218:     return { ok: false, reason: 'Every copy is already equipped' };
219:   }
220:   return { ok: true };
221: }
