379:     ctx.fillRect(-500, -200, 1000, 800);
380: 
381:     const sortedTiles = [...B.tiles].sort((a, b) => (a.x + a.y) - (b.x + b.y) || a.x - b.x);
382:     for (const t of sortedTiles) drawTile(t);
383: 
384:     drawOverlay(B.moveSet, 'rgba(121,192,180,0.16)', 'rgba(121,192,180,0.35)');
385:     drawOverlay(B.threatSet, 'rgba(163,68,74,0.12)', 'rgba(163,68,74,0.22)');
386:     drawOverlay(B.attackSet, 'rgba(214,181,106,0.18)', 'rgba(214,181,106,0.45)');
387:     drawOverlay(B.aoeSet, 'rgba(214,120,70,0.28)', 'rgba(240,150,90,0.7)');
388: 
389:     // path preview
390:     if (B.pathSet && B.pathSet.length > 1) {
391:       ctx.save();
392:       ctx.strokeStyle = 'rgba(240,215,149,0.75)';
393:       ctx.lineWidth = 2;
394:       ctx.setLineDash([4, 4]);
395:       ctx.beginPath();
396:       B.pathSet.forEach((k, i) => {
397:         const [x, y] = k.split(',').map(Number);
398:         const p = iso(x, y, tileAt(x, y)?.elev || 0);
399:         if (i === 0) ctx.moveTo(p.x, p.y);
400:         else ctx.lineTo(p.x, p.y);
401:       });
402:       ctx.stroke();
403:       ctx.restore();
404:     }
405: 
406:     // hover outline
407:     if (B.pointerTile) {
408:       const t = tileAt(B.pointerTile.x, B.pointerTile.y);
409:       if (t) {
410:         const p = iso(t.x, t.y, t.elev);
411:         ctx.strokeStyle = 'rgba(240,231,206,0.55)';
412:         ctx.lineWidth = 1.4;
413:         ctx.beginPath();
414:         ctx.moveTo(p.x, p.y - TH / 2);
415:         ctx.lineTo(p.x + TW / 2, p.y);
416:         ctx.lineTo(p.x, p.y + TH / 2);
417:         ctx.lineTo(p.x - TW / 2, p.y);
418:         ctx.closePath();
419:         ctx.stroke();
420:       }
421:     }
422: 
423:     const sortedUnits = [...B.units].sort((a, b) => (a.x + a.y) - (b.x + b.y) || a.x - b.x);
424:     for (const u of sortedUnits) drawUnit(u);
425: 
426:     // particles
427:     for (const p of B.particles) {
428:       ctx.globalAlpha = clamp(p.life / p.max, 0, 1);
429:       ctx.fillStyle = p.color;
430:       ctx.fillRect(p.x, p.y, p.size, p.size);
431:     }
432:     ctx.globalAlpha = 1;
433: 
434:     // floaters
435:     ctx.textAlign = 'center';
436:     ctx.font = 'bold 13px "Courier New", monospace';
437:     for (const f of B.floaters) {
438:       const a = clamp(f.life / f.max, 0, 1);
439:       ctx.globalAlpha = a;
440:       ctx.fillStyle = '#050407';
441:       ctx.fillText(f.text, f.x + 1, f.y - (1 - a) * 26 + 1);
442:       ctx.fillStyle = f.color;
443:       ctx.fillText(f.text, f.x, f.y - (1 - a) * 26);
444:     }
445:     ctx.globalAlpha = 1;
446:     ctx.restore();
447: 
448:     // vignette
449:     const vig = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.28, w / 2, h / 2, Math.max(w, h) * 0.75);
450:     vig.addColorStop(0, 'rgba(0,0,0,0)');
451:     vig.addColorStop(1, 'rgba(0,0,0,0.55)');
452:     ctx.fillStyle = vig;
453:     ctx.fillRect(0, 0, w, h);
454:   }
