476:   function forecastOrder(n = 9) {
477:     const sim = living().map(u => ({ u, ct: u.ct, gain: ctGain(u) }));
478:     const out = [];
479:     let guard = 0;
480:     while (out.length < n && guard++ < 400) {
481:       for (const s of sim) s.ct += s.gain;
482:       const ready = sim.filter(s => s.ct >= 100).sort((a, b) => b.ct - a.ct);
483:       for (const s of ready) {
484:         if (out.length >= n) break;
485:         out.push(s.u);
486:         s.ct -= 100;
487:       }
488:     }
489:     return out;
490:   }
