697:   /* ---------------- combat math ---------------- */
698:   function basicAttack(u) {
699:     const w = u.stats.weapon;
700:     const magical = (w.mag || 0) > (w.atk || 0);
701:     return {
702:       id: 'weapon', name: 'Attack', desc: '', mp: 0,
703:       range: w.range || 1, aoe: 0, power: 100,
704:       kind: magical ? 'mag' : 'phys', target: 'enemy', affect: 'enemies',
705:     };
706:   }
707:   function artRange(art, u) { return art.range ?? u.stats.weapon.range; }
708:   function facingDir(from, to) {
709:     const dx = to.x - from.x, dy = to.y - from.y;
710:     if (Math.abs(dx) > Math.abs(dy)) return dx > 0 ? 'e' : 'w';
711:     return dy > 0 ? 's' : 'n';
712:   }
713:   function facingBonus(a, d) {
714:     const dir = facingDir(d, a);
715:     if (dir === OPPOSITE[d.facing]) return 1.2;
716:     if (dir === d.facing) return 0.9;
717:     return 1;
718:   }
719:   function hitChance(a, d) {
720:     let hit = 91 + (eff(a, 'spd') - eff(d, 'spd')) * 0.8;
721:     const t = tileAt(d.x, d.y);
722:     if (t) hit -= t.terrain.evade || 0;
723:     if (has(d, 'evade')) hit -= statusVal(d, 'evade');
724:     if (tileElev(a) > tileElev(d)) hit += 4;
725:     return clamp(hit, 55, 99);
726:   }
727:   function critChance(a, art) {
728:     let c = 6 + (a.stats.luck || 0) * 0.4 + (art?.critBonus || 0) * 100;
729:     if (has(a, 'focus')) c += statusVal(a, 'focus');
730:     return clamp(c, 2, 60);
731:   }
732:   function estimateDamage(a, d, art) {
733:     const kind = art?.kind || 'phys';
734:     const w = a.stats.weapon;
735:     let atk, mit;
736:     if (kind === 'mag') {
737:       atk = eff(a, 'ma') + (w.mag || 0);
738:       mit = eff(d, 'res');
739:     } else if (kind === 'hybrid') {
740:       atk = ((eff(a, 'pa') + (w.atk || 0)) + (eff(a, 'ma') + (w.mag || 0))) / 2;
741:       mit = (eff(d, 'def') + eff(d, 'res')) / 2;
742:     } else {
743:       atk = eff(a, 'pa') + (w.atk || 0);
744:       mit = eff(d, 'def');
745:     }
746:     if (art?.pierce) mit *= 1 - art.pierce;
747:     let dmg = atk * ((art?.power || 100) / 100) - mit * 0.62;
748:     const hd = tileElev(a) - tileElev(d);
749:     dmg *= 1 + clamp(hd, -1, 1) * 0.1;
750:     dmg *= facingBonus(a, d);
751:     if (art?.execute && d.hp < d.stats.maxHp * 0.5) dmg *= 1.6;
752:     return Math.max(1, dmg);
753:   }
754:   function healPower(caster, art) {
755:     return Math.max(1, Math.round((art.power || 100) / 100 * eff(caster, 'ma') * 1.15 + 16));
756:   }
757: 
758:   function damageUnit(source, target, amount, art, opts = {}) {
759:     if (target.dead) return 0;
760:     let dmg = Math.max(1, Math.round(amount));
761:     const shield = target.statuses.find(s => s.id === 'shield');
762:     if (shield && shield.value > 0) {
763:       const absorbed = Math.min(shield.value, dmg);
764:       shield.value -= absorbed;
765:       dmg -= absorbed;
766:       if (absorbed > 0) floater(...Object.values(unitPoint(target)), `-${absorbed} shield`, '#79c0b4');
767:       if (shield.value <= 0) target.statuses = target.statuses.filter(s => s !== shield);
768:     }
769:     if (dmg <= 0) return 0;
770:     target.hp = Math.max(0, target.hp - dmg);
771:     const p = unitPoint(target);
772:     floater(p.x, p.y - 30, `-${dmg}`, opts.crit ? '#ffb066' : '#f0d795');
773:     burst(p.x, p.y - 16, opts.crit ? '#ffb066' : '#c9a96a', opts.crit ? 20 : 10);
774:     if (opts.crit) { shake(7); sfx('crit'); } else { shake(2.4); sfx('hit'); }
775:     if (target.hp <= 0) killUnit(target, source);
776:     return dmg;
777:   }
778:   function healUnit(target, amount) {
779:     if (target.dead) return 0;
780:     const before = target.hp;
781:     target.hp = Math.min(target.stats.maxHp, target.hp + Math.max(1, Math.round(amount)));
782:     const healed = target.hp - before;
783:     if (healed > 0) {
784:       const p = unitPoint(target);
785:       floater(p.x, p.y - 30, `+${healed}`, '#8fc09a');
786:       burst(p.x, p.y - 14, '#79c0b4', 8);
787:       sfx('heal');
788:     }
789:     return healed;
790:   }
791:   function killUnit(u, source) {
792:     if (u.dead) return;
793:     u.dead = true;
794:     u.hp = 0;
795:     u.ct = -999;
796:     u.statuses = [];
797:     const p = unitPoint(u);
798:     burst(p.x, p.y - 12, u.side === 'player' ? '#79c0b4' : '#b05257', 22);
799:     log(`<strong>${esc(u.name)}</strong> falls.`, u.side === 'player' ? 'enemy' : 'player');
800:     if (u.side === 'enemy') {
801:       B.kills += 1;
802:       if (u.dropId && (u.boss || Math.random() < (u.dropChance || 0.34))) {
803:         B.loot.push({ id: u.dropId, qty: 1, source: u.name });
804:         log(`${esc(u.name)} drops <strong>${esc(ITEM_MAP[u.dropId]?.name || u.dropId)}</strong>.`, 'gold');
805:       } else if (Math.random() < 0.2) {
806:         const id = rollLoot(B.chapterIndex);
807:         B.loot.push({ id, qty: 1, source: u.name });
808:         log(`${esc(u.name)} drops <strong>${esc(ITEM_MAP[id]?.name || id)}</strong>.`, 'gold');
809:       }
