143: function drawTitle(ts) {
144:   const canvas = $('#title-canvas');
145:   if (!canvas) { titleRaf = 0; return; }
146:   const dpr = Number(canvas.dataset.dpr) || 1;
147:   const w = canvas.width / dpr;
148:   const h = canvas.height / dpr;
149:   const ctx = canvas.getContext('2d');
150:   ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
151:   const dt = Math.min(0.05, (ts - (titleLast || ts)) / 1000);
152:   titleLast = ts;
153: 
154:   ctx.clearRect(0, 0, w, h);
155:   const bg = ctx.createLinearGradient(0, 0, 0, h);
156:   bg.addColorStop(0, '#120d17');
157:   bg.addColorStop(0.5, '#08070a');
158:   bg.addColorStop(1, '#050407');
159:   ctx.fillStyle = bg;
160:   ctx.fillRect(0, 0, w, h);
161: 
162:   // distant ruined skyline
163:   ctx.fillStyle = 'rgba(9, 7, 12, 0.9)';
164:   const horizon = h * 0.72;
165:   for (let i = 0; i < 9; i++) {
166:     const bw = w * (0.03 + ((i * 37) % 7) * 0.006);
167:     const bh = h * (0.04 + ((i * 53) % 11) * 0.012);
168:     const bx = (i / 8) * w - bw / 2;
169:     ctx.fillRect(bx, horizon - bh, bw, bh);
170:   }
171:   ctx.fillStyle = 'rgba(214,181,106,0.05)';
172:   ctx.fillRect(0, horizon, w, 1);
173: 
174:   // faint crown behind the title
175:   ctx.save();
176:   ctx.globalAlpha = 0.07 + Math.sin(ts / 2400) * 0.015;
177:   drawCrown(ctx, w / 2, h * 0.24, Math.max(4, Math.round(Math.min(w, h) / 100)));
178:   ctx.restore();
179: 
180:   // embers
181:   for (const p of titleParticles) {
182:     p.x += p.vx * dt;
183:     p.y -= p.vy * dt;
184:     if (p.y < -10 || p.x < -10 || p.x > w + 10) {
185:       p.x = Math.random() * w;
186:       p.y = h + 10 + Math.random() * 30;
187:     }
188:     ctx.globalAlpha = p.a * (0.55 + Math.sin((ts / 800) + p.x) * 0.2);
189:     ctx.fillStyle = p.warm ? '#d6b56a' : '#79c0b4';
190:     ctx.fillRect(Math.round(p.x), Math.round(p.y), Math.ceil(p.r), Math.ceil(p.r));
191:   }
192:   ctx.globalAlpha = 1;
193: 
194:   titleRaf = requestAnimationFrame(drawTitle);
