814: /* ============================================================
815:    DEPLOYMENT & BATTLE HAND-OFF
816:    ============================================================ */
817: function deploy() {
818:   if (!state || state.completed) return;
819:   const enc = currentEncounter(state);
820:   if (!enc) { toast('There is no road left to march'); return; }
821:   if (!deployedUnits(state).length) { toast('Choose at least one companion to march'); return; }
822:   persist();
823:   if (!state.seenIntros.includes(enc.id)) {
824:     state.seenIntros.push(enc.id);
825:     persist();
826:     playStory(enc.intro, () => launchBattle(enc));
827:   } else {
828:     launchBattle(enc);
829:   }
830: }
831: 
832: function launchBattle(enc) {
833:   showScreen('battle-screen');
834:   const root = $('#board-wrap');
835:   if (root) root.scrollTop = 0;
836:   currentBattle = startBattle({
837:     state,
838:     encounter: enc,
839:     onEnd: (result) => handleBattleEnd(enc, result),
840:   });
841: }
842: 
843: function handleBattleEnd(enc, result) {
844:   currentBattle = null;
845:   if (result.victory) {
846:     const summary = applyVictory(enc, result);
847:     showResult(enc, result, summary);
848:   } else {
849:     state.stats.battles += 1;
850:     persist();
851:     showResult(enc, result, null);
852:   }
853: }
854: 
855: function applyVictory(enc, result) {
856:   // Supplies are consumed only on a victory.
857:   for (const [id, qty] of Object.entries(result.usedItems || {})) {
858:     state.inventory[id] = Math.max(0, (state.inventory[id] || 0) - qty);
859:   }
860: 
861:   const reward = enc.rewards || { gold: 0, jp: 0, exp: 0, items: [] };
862:   const gold = (reward.gold || 0) + (result.stolenGold || 0);
863:   state.gold += gold;
864:   state.stats.goldEarned += gold;
865: 
866:   const loot = [];
867:   for (const drop of result.loot || []) {
868:     addItem(state, drop.id, drop.qty || 1);
869:     loot.push({ id: drop.id, qty: drop.qty || 1, source: drop.source });
870:   }
871:   for (const item of reward.items || []) {
872:     addItem(state, item.id, item.qty || 1);
873:     loot.push({ id: item.id, qty: item.qty || 1, source: 'Chapter reward' });
874:   }
875: 
876:   const levelUps = [];
877:   for (const unit of deployedUnits(state)) {
878:     const before = unit.level;
879:     const gained = grantExp(unit, reward.exp || 0);
880:     grantJp(unit, reward.jp || 0);
881:     if (gained > 0) levelUps.push({ unit, from: before, to: unit.level });
882:   }
883: 
884:   const recruits = [];
885:   for (const id of enc.recruits || []) {
886:     const unit = recruitUnit(state, id);
887:     if (unit) recruits.push(unit);
888:   }
889: 
890:   state.stats.battles += 1;
891:   state.stats.victories += 1;
892:   state.stats.kills += result.kills || 0;
893:   state.stats.turns += result.turns || 0;
894: 
895:   advanceEncounter(state);
896:   persist();
897: 
898:   return {
899:     gold,
900:     exp: reward.exp || 0,
901:     jp: reward.jp || 0,
902:     loot,
903:     levelUps,
904:     recruits,
905:     usedItems: result.usedItems || {},
906:     stolenGold: result.stolenGold || 0,
907:   };
908: }
