961:     `<div class="level-up"><strong>${esc(l.unit.name)}</strong> reached Lv ${l.to}${l.to > l.from + 1 ? ` (+${l.to - l.from})` : ''}.</div>`
962:   ).join('');
963:   const recruits = (summary.recruits || []).map(u =>
964:     `<div class="level-up"><strong>${esc(u.name)}</strong> joined the company as a ${esc(jobOf(u).name)}.</div>`
965:   ).join('');
966: 
967:   if (body) {
968:     body.innerHTML = `
969:       <p class="dialog-text" style="text-align:center;margin-top:0">${esc(enc.title)} — ${esc(enc.objective)}.</p>
970:       <div class="reward-grid">
971:         <div class="reward"><span>Gold</span><strong>${summary.gold}</strong></div>
972:         <div class="reward"><span>EXP each</span><strong>${summary.exp}</strong></div>
973:         <div class="reward"><span>JP each</span><strong>${summary.jp}</strong></div>
974:         <div class="reward"><span>Turns</span><strong>${result.turns}</strong></div>
975:         <div class="reward"><span>Foes felled</span><strong>${result.kills}</strong></div>
976:       </div>
977:       ${lootChips ? `<div class="section-title">Spoils</div><div class="loot-list">${lootChips}</div>` : ''}
978:       ${levels ? `<div class="section-title">Levels</div><div class="level-up-list">${levels}</div>` : ''}
979:       ${recruits ? `<div class="section-title">New Companions</div><div class="level-up-list">${recruits}</div>` : ''}
980:       <div class="result-note">
981:         Downed companions recover at camp.${state.completed ? ' The road is complete — the hollow crown is buried under salt.' : ' The next chapter waits on the road north.'}
982:       </div>`;
