456:   function frame(ts) {
457:     if (B.destroyed) return;
458:     const dt = Math.min(0.05, (ts - (B._last || ts)) / 1000);
459:     B._last = ts;
460:     B.time = ts / 1000;
461:     B.shake = Math.max(0, B.shake - dt * 34);
462:     for (const f of B.floaters) { f.life -= dt; f.y -= dt * 18; }
463:     B.floaters = B.floaters.filter(f => f.life > 0);
464:     for (const p of B.particles) {
465:       p.life -= dt;
466:       p.x += p.vx * dt;
467:       p.y += p.vy * dt;
468:       p.vy += 150 * dt;
469:     }
470:     B.particles = B.particles.filter(p => p.life > 0);
471:     draw();
472:     B.raf = requestAnimationFrame(frame);
473:   }
