701:   /* ---------------- combat math ---------------- */
702:   function basicAttack(u) {
703:     const w = u.stats.weapon;
704:     const magical = (w.mag || 0) > (w.atk || 0);
705:     return {
706:       id: 'weapon', name: 'Attack', desc: '', mp: 0,
707:       range: w.range || 1, aoe: 0, power: 100,
708:       kind: magical ? 'mag' : 'phys', target: 'enemy', affect: 'enemies',
709:     };
710:   }
711:   function artRange(art, u) { return art.range ?? u.stats.weapon.range; }
712:   function facingDir(from, to) {
713:     const dx = to.x - from.x, dy = to.y - from.y;
714:     if (Math.abs(dx) > Math.abs(dy)) return dx > 0 ? 'e' : 'w';
715:     return dy > 0 ? 's' : 'n';
716:   }
717:   function facingBonus(a, d) {
718:     const dir = facingDir(d, a);
719:     if (dir === OPPOSITE[d.facing]) return 1.2;
720:     if (dir === d.facing) return 0.9;
721:     return 1;
722:   }
723:   function hitChance(a, d) {
724:     let hit = 91 + (eff(a, 'spd') - eff(d, 'spd')) * 0.8;
725:     const t = tileAt(d.x, d.y);
726:     if (t) hit -= t.terrain.evade || 0;
727:     if (has(d, 'evade')) hit -= statusVal(d, 'evade');
728:     if (tileElev(a) > tileElev(d)) hit += 4;
729:     return clamp(hit, 55, 99);
730:   }
731:   function critChance(a, art) {
732:     let c = 6 + (a.stats.luck || 0) * 0.4 + (art?.critBonus || 0) * 100;
733:     if (has(a, 'focus')) c += statusVal(a, 'focus');
734:     return clamp(c, 2, 60);
735:   }
736:   function estimateDamage(a, d, art) {
737:     const kind = art?.kind || 'phys';
738:     const w = a.stats.weapon;
739:     let atk, mit;
740:     if (kind === 'mag') {
741:       atk = eff(a, 'ma') + (w.mag || 0);
742:       mit = eff(d, 'res');
743:     } else if (kind === 'hybrid') {
744:       atk = ((eff(a, 'pa') + (w.atk || 0)) + (eff(a, 'ma') + (w.mag || 0))) / 2;
745:       mit = (eff(d, 'def') + eff(d, 'res')) / 2;
746:     } else {
747:       atk = eff(a, 'pa') + (w.atk || 0);
748:       mit = eff(d, 'def');
749:     }
750:     if (art?.pierce) mit *= 1 - art.pierce;
751:     let dmg = atk * ((art?.power || 100) / 100) - mit * 0.62;
752:     const hd = tileElev(a) - tileElev(d);
753:     dmg *= 1 + clamp(hd, -1, 1) * 0.1;
754:     dmg *= facingBonus(a, d);
755:     if (art?.execute && d.hp < d.stats.maxHp * 0.5) dmg *= 1.6;
756:     return Math.max(1, dmg);
757:   }
758:   function healPower(caster, art) {
759:     return Math.max(1, Math.round((art.power || 100) / 100 * eff(caster, 'ma') * 1.15 + 16));
760:   }
761: 
762:   function damageUnit(source, target, amount, art, opts = {}) {
763:     if (target.dead) return 0;
764:     let dmg = Math.max(1, Math.round(amount));
765:     const shield = target.statuses.find(s => s.id === 'shield');
766:     if (shield && shield.value > 0) {
767:       const absorbed = Math.min(shield.value, dmg);
768:       shield.value -= absorbed;
769:       dmg -= absorbed;
770:       if (absorbed > 0) floater(...Object.values(unitPoint(target)), `-${absorbed} shield`, '#79c0b4');
771:       if (shield.value <= 0) target.statuses = target.statuses.filter(s => s !== shield);
772:     }
773:     if (dmg <= 0) return 0;
774:     target.hp = Math.max(0, target.hp - dmg);
775:     const p = unitPoint(target);
776:     floater(p.x, p.y - 30, `-${dmg}`, opts.crit ? '#ffb066' : '#f0d795');
777:     burst(p.x, p.y - 16, opts.crit ? '#ffb066' : '#c9a96a', opts.crit ? 20 : 10);
778:     if (opts.crit) { shake(7); sfx('crit'); } else { shake(2.4); sfx('hit'); }
779:     if (target.hp <= 0) killUnit(target, source);
780:     return dmg;
781:   }
782:   function healUnit(target, amount) {
783:     if (target.dead) return 0;
784:     const before = target.hp;
785:     target.hp = Math.min(target.stats.maxHp, target.hp + Math.max(1, Math.round(amount)));
786:     const healed = target.hp - before;
787:     if (healed > 0) {
788:       const p = unitPoint(target);
789:       floater(p.x, p.y - 30, `+${healed}`, '#8fc09a');
790:       burst(p.x, p.y - 14, '#79c0b4', 8);
791:       sfx('heal');
792:     }
793:     return healed;
794:   }
795:   function killUnit(u, source) {
796:     if (u.dead) return;
797:     u.dead = true;
798:     u.hp = 0;
799:     u.ct = -999;
800:     u.statuses = [];
801:     const p = unitPoint(u);
802:     burst(p.x, p.y - 12, u.side === 'player' ? '#79c0b4' : '#b05257', 22);
803:     log(`<strong>${esc(u.name)}</strong> falls.`, u.side === 'player' ? 'enemy' : 'player');
804:     if (u.side === 'enemy') {
805:       B.kills += 1;
806:       if (u.dropId && (u.boss || Math.random() < (u.dropChance || 0.34))) {
807:         B.loot.push({ id: u.dropId, qty: 1, source: u.name });
808:         log(`${esc(u.name)} drops <strong>${esc(ITEM_MAP[u.dropId]?.name || u.dropId)}</strong>.`, 'gold');
809:       } else if (Math.random() < 0.2) {
810:         const id = rollLoot(B.chapterIndex);
811:         B.loot.push({ id, qty: 1, source: u.name });
812:         log(`${esc(u.name)} drops <strong>${esc(ITEM_MAP[id]?.name || id)}</strong>.`, 'gold');
813:       }
814:       if (u.boss) { shake(9); sfx('crit'); }
815:     }
816:     if (u.uid === B.active?.uid) {
817:       B.active = null;
818:       B.mode = 'idle';
819:       clearTargets();
820:       setTimeout(() => { if (!B.over && !B.destroyed) endTurn(); }, 420);
821:     }
