824:   /* ---------------- movement ---------------- */
825:   function computeReachable(u) {
826:     const start = KEY(u.x, u.y);
827:     const best = { [start]: 0 };
828:     const prev = {};
829:     const startElev = tileElev(u);
830:     const queue = [{ x: u.x, y: u.y, cost: 0 }];
831:     while (queue.length) {
832:       queue.sort((a, b) => a.cost - b.cost);
833:       const cur = queue.shift();
834:       const curKey = KEY(cur.x, cur.y);
835:       if (cur.cost > (best[curKey] ?? Infinity)) continue;
836:       const curElev = tileAt(cur.x, cur.y)?.elev || 0;
837:       for (const d of DIRS) {
838:         const nx = cur.x + d.x, ny = cur.y + d.y;
839:         const nt = tileAt(nx, ny);
840:         if (!nt || nt.block) continue;
841:         const occ = unitAt(nx, ny);
842:         if (occ && occ.side !== u.side) continue;
843:         const dz = nt.elev - curElev;
844:         if (dz > u.stats.jump) continue;
845:         const nc = cur.cost + (nt.terrain.cost || 1) + Math.max(0, dz) * 2;
846:         if (nc > u.stats.move) continue;
847:         const k = KEY(nx, ny);
848:         if (best[k] === undefined || nc < best[k]) {
849:           best[k] = nc;
850:           prev[k] = curKey;
851:           queue.push({ x: nx, y: ny, cost: nc });
852:         }
853:       }
854:     }
855:     const paths = {};
856:     for (const k of Object.keys(best)) {
857:       const path = [];
858:       let cur = k;
859:       let guard = 0;
860:       while (cur && guard++ < 100) {
861:         path.unshift(cur);
862:         cur = prev[cur];
863:       }
