1214:         toast('No fallen ally there');
1215:       }
1216:       for (const ally of fallen) {
1217:         ally.dead = false;
1218:         const pct = art.power > 1 ? art.power / 100 : (art.power || 0.5);
1219:         ally.hp = Math.max(1, Math.round(ally.stats.maxHp * pct));
